UPDATE club_member
SET role_name = #{roleName}
WHERE club_id = #{clubId}
  AND oauth_user_id = #{oauthUserId}

UPDATE club_member
SET role_name = 'member'
WHERE club_id = #{clubId}
  AND oauth_user_id != #{oauthUserId}
  AND LOWER(role_name) = 'president'

UPDATE club_membership_requests
SET status = #{status},
    reviewed_at = CURRENT_TIMESTAMP,
    reviewed_by_oauth_user_id = #{reviewedByOauthUserId},
    note = #{note}
WHERE id = #{id}
